        {
            "question": "What decision thresholds are used?",
            "ground_truth": [
                {"sentence": "The model outputs a continuous score, and the paper reports only threshold-free metrics (AUC, AP).", "section": "performance", "field": "thresholds"},
                {"sentence": "The MeVer API converts the score into an evidence label using three thresholds set on the real images of ITW-SM, each at a fixed false-positive rate (FPR):", "section": "performance", "field": "thresholds"},
                {"sentence": "VERY\\_STRONG\\_EVIDENCE: the score reaches the threshold at which 1% of ITW-SM real images are flagged.", "section": "performance", "field": "thresholds"},
                {"sentence": "STRONG\\_EVIDENCE: the score reaches the 5% threshold but not the 1% one.", "section": "performance", "field": "thresholds"},
                {"sentence": "MODERATE\\_EVIDENCE: the score reaches the 10% threshold but not the 5% one.", "section": "performance", "field": "thresholds"},
                {"sentence": "WEAK\\_EVIDENCE: the score is below the 10% threshold; by construction, about 90% of ITW-SM real images fall here.", "section": "performance", "field": "thresholds"},
                {"sentence": "The rates are cumulative: on ITW-SM, about 10% of real images receive MODERATE\\_EVIDENCE or a stronger label, about 5% STRONG\\_EVIDENCE or stronger, and about 1% VERY\\_STRONG\\_EVIDENCE.", "section": "performance", "field": "thresholds"},
                {"sentence": "They say how often authentic images are flagged, not how likely a flagged image is to be AI-generated; that also depends on how common AI images are among the images checked and on the detection rate at each threshold, and detection rates at these thresholds are not reported.", "section": "performance", "field": "thresholds"},
                {"sentence": "The rates were measured on the same data the thresholds were set on and can differ on other platforms, processing chains or content.", "section": "performance", "field": "thresholds"},
                {"sentence": "The 10% threshold is far below 0.5: in a small API test on 1 October 2026, an AI-generated image scoring 0.0137 was labelled MODERATE\\_EVIDENCE, so this threshold is at or below that value.", "section": "performance", "field": "thresholds"},
                {"sentence": "The raw score should therefore not be compared with 0.5.", "section": "performance", "field": "thresholds"},
                {"sentence": "The numeric threshold values are not published.", "section": "performance", "field": "thresholds"},
            ],
        },
        {
            "question": "What is the evaluation methodology?",
            "ground_truth": [
                {"sentence": "AUC (area under the ROC curve) and AP (average precision) are computed per test set over all its real and AI-generated images, with AI-generated images as the positive class, and the average is the plain mean over the three test sets.", "section": "performance", "field": "methodology"},
                {"sentence": "The paper reports a single result per configuration: no repeated runs, standard deviations or confidence intervals.", "section": "performance", "field": "methodology"},
                {"sentence": "AP depends on the class balance of each set (Synthbuster has nine generated images per real one, ITW-SM is balanced), so AP values are not comparable across sets.", "section": "performance", "field": "methodology"},
                {"sentence": "The thresholds behind the API's evidence labels were set on the scores of ITW-SM real images at fixed false-positive rates of 1%, 5% and 10%.", "section": "performance", "field": "methodology"},
                {"sentence": "No independent evaluation of the deployed service is reported.", "section": "performance", "field": "methodology"},
            ],
        },
